rule.example:

fn choose(flag: bool) -> i32 {
    if flag {
        1
    } else {
        2
    }
}


fn scan(mut x: i32) {
    if { x = 1; true } {
        let _ = x;
    }
}


struct Point { x: i32, y: i32 }
fn make() -> Point {
    Point { x: 1, y: 2, x: 3 }
}


struct Helper;
impl Helper {
    fn make() -> i32 { 1 }
}
struct Worker;
impl Worker {
    fn run() -> i32 {
        Helper::make()
    }
}
